export function canonicalPatternId(id: string): string {
  return PATTERN_ALIASES[id] ?? id;
}

/** Canonical id -> merged duplicate ids. */
export function aliasesOf(id: string): string[] {
  return Object.keys(PATTERN_ALIASES).filter((a) => PATTERN_ALIASES[a] === id);
}

export const CANONICAL_PATTERN_IDS: string[] = PATTERN_IDS.filter((id) => !(id in PATTERN_ALIASES));
